const markDeathSaveRolledOnTurn = `-- name: MarkDeathSaveRolledOnTurn :exec
UPDATE combatants
SET death_save_rolled = true
WHERE character_id = $1
  AND kind = 'player'
  AND turn_state = 'acting'
  AND encounter_id IN (
      SELECT id FROM encounters
      WHERE game_session_id = $2 AND status = 'active'
  )
`

type MarkDeathSaveRolledOnTurnParams struct {
	CharacterID   string
	GameSessionID string
}

// A character that drops to 0 hit points during its own turn owes no death save
// until its next turn starts (SRD 5.1: the save is rolled at the start of the
// turn), so this turn's save counts as done. Only a combatant who acts in the
// turn, in the session's active combat.
func (q *Queries) MarkDeathSaveRolledOnTurn(ctx context.Context, arg MarkDeathSaveRolledOnTurnParams) error {
	_, err := q.db.Exec(ctx, markDeathSaveRolledOnTurn, arg.CharacterID, arg.GameSessionID)
	return err
}

const nextSessionEventSeq = `-- name: NextSessionEventSeq :one
SELECT (COALESCE(max(seq), 0) + 1)::INT4 AS next
FROM session_events
WHERE game_session_id = $1
`

// Events count from 1 in each session. The caller holds the session's row
// lock (GetOpenGameSessionForUpdate), so no other change reads the same
// number; UNIQUE (game_session_id, seq) is the backstop.
func (q *Queries) NextSessionEventSeq(ctx context.Context, gameSessionID string) (int32, error) {
	row := q.db.QueryRow(ctx, nextSessionEventSeq, gameSessionID)
	var next int32
	err := row.Scan(&next)
	return next, err
}

const nextSessionNumber = `-- name: NextSessionNumber :one
SELECT (COALESCE(max(session_number), 0) + 1)::INT4 AS next
FROM game_sessions
WHERE campaign_id = $1
`

// Sessions count from 1. Two starts racing both read the same number;
// CockroachDB's SERIALIZABLE isolation makes one of them retry, and the
// UNIQUE (campaign_id, session_number) constraint is the backstop.
func (q *Queries) NextSessionNumber(ctx context.Context, campaignID string) (int32, error) {
	row := q.db.QueryRow(ctx, nextSessionNumber, campaignID)
	var next int32
	err := row.Scan(&next)
	return next, err
}

